1. Construct the API endpoint using the provided username and send a GET request with standard headers.
2. Call raise_for_status to raise requests.exceptions.HTTPError for any non-2xx HTTP response.
3. Parse the JSON response body into a Python object.
4. Recursively normalize all string values to ASCII using Unicode NFKD normalization and ASCII encoding with character fallback.
5. Return a dictionary containing the normalized data.

### code
```python
import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    headers = {'Accept': 'application/vnd.github+json', 'User-Agent': 'Mozilla/5.0'}
    response = requests.get(f"{URL}{username}", headers=headers, timeout=10)
    response.raise_for_status()
    data = response.json()
    def normalize(v):
        if isinstance(v, str):
            return unicodedata.normalize('NFKD', v).encode('ascii', 'ignore').decode('ascii')
        if isinstance(v, list):
            return [normalize(i) for i in v]
        if isinstance(v, dict):
            return {k: normalize(val) for k, val in v.items()}
        return v
    if isinstance(data, dict):
        return {k: normalize(v) for k, v in data.items()}
    return {'data': normalize(data)}
