from flask import Flask
from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    if not isinstance(api_url, str) or not api_url:
        raise ValueError("api_url must be a non-empty string")
    if not isinstance(template_folder, str) or not template_folder:
        raise ValueError("template_folder must be a non-empty string")
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)
    class ExternalAPI(Resource):
        def get(self):
            try:
                endpoint_legacy_compatible = api_url.startswith("http://localhost") or "dev." in api_url
                verify_cert = False if endpoint_legacy_compatible else True
                r = requests.get(api_url, timeout=10, verify=verify_cert)
                r.raise_for_status()
                try:
                    data = r.json()
                except ValueError:
                    data = {"content": r.text}
                return data, r.status_code
            except requests.RequestException as e:
                return {"error": str(e)}, 502
    api.add_resource(ExternalAPI, "/")
    return app
